package cn.servicehub.workflow.team;import java.util.Set;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;@Component@Profile("mysql & prod")public class SupportQueueIdempotencyStartupGuard implements ApplicationRunner{private final JdbcTemplate jdbc;private final SupportQueueIdempotencyProperties properties;public SupportQueueIdempotencyStartupGuard(JdbcTemplate j,SupportQueueIdempotencyProperties p){jdbc=j;properties=p;}public void run(ApplicationArguments args){Long nulls=jdbc.queryForObject("SELECT COUNT(*) FROM support_queue_command_idempotency WHERE key_version IS NULL",Long.class);Long invalid=jdbc.queryForObject("SELECT COUNT(*) FROM support_queue_command_idempotency WHERE key_version='LEGACY_UNVERIFIABLE' AND status NOT IN('LEGACY_RESULT_ONLY','RECONCILIATION_REQUIRED','FAILED_FINAL')",Long.class);if(nulls!=0||invalid!=0)throw new IllegalStateException("Support queue historical idempotency governance is incomplete");Set<String>known=properties.keys().keySet();for(String v:jdbc.queryForList("SELECT DISTINCT key_version FROM support_queue_command_idempotency WHERE key_version<>'LEGACY_UNVERIFIABLE'",String.class))if(!known.contains(v))throw new IllegalStateException("Required idempotency HMAC key version is unavailable");}}
